}

const keywords = (cfg.company?.keywords_include || []).map(k => String(k).toLowerCase());
const cap = Math.max(1, Number(A.max_companies_per_run || 400));
const threadsWanted = Math.max(1, Math.min(4, Number(A.threads || 2)));
// Signal gate: a post must mention at least one GTM-specific keyword, not only a generic one like "b2b"
const strong = (Array.isArray(A.strong_keywords) ? A.strong_keywords : []).map(k => String(k).toLowerCase());

// Per-gate counters: telemetry first, never a blind rewrite again
const C = { threads: 0, top_level: 0, keyword_hits: 0, weak_drop: 0, url_fail: 0, dup_drop: 0, tz_null: 0 };

const NOISE_HOSTS = [
  'workable.com','greenhouse.io','lever.co','ashbyhq.com','smartrecruiters.com',
  'indeed.com','glassdoor.com','linkedin.com','github.com','twitter.com','x.com',
  'medium.com','wikipedia.org','youtube.com','docs.google.com','forms.gle',
  'news.ycombinator.com','hn.algolia.com',
  // personal sites, site builders and job boards are not companies
  'vercel.app','netlify.app','github.io','notion.site','notion.so','webflow.io','carrd.co',
  'substack.com','calendly.com','typeform.com','google.com','bit.ly','t.co','linktr.ee',
  'nordictechjobs.com','mycreportfolio.com','wellfound.com','angel.co','ycombinator.com',
  'workatastartup.com','breezy.hr','recruitee.com','teamtailor.com','bamboohr.com','personio.de',
  'personio.com','rippling.com','gem.com','jobvite.com','icims.com','myworkdayjobs.com','notion.com'
].concat((Array.isArray(A.extra_noise_hosts) ? A.extra_noise_hosts : []).map(h => String(h).toLowerCase()));
const ATS_PREFIXES = ['ats.', 'jobs.', 'careers.', 'apply.', 'boards.', 'hire.', 'recruiting.'];

const HOST_RE = /https?:\/\/(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}/i;
const URL_RE  = /https?:\/\/(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}(?:\/[^\s<>"']*)?/gi;

// whole-word match, so "clay" does not match "barclays"
const hasWord = (text, k) => new RegExp('(^|[^a-z0-9])' + k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '([^a-z0-9]|$)').test(text);

const isNoise = (host) => NOISE_HOSTS.some(n => host === n || host.endsWith('.' + n));

function cleanHost(host) {
  host = host.replace(/^https?:\/\//i, '').toLowerCase().replace(/^www\./, '');
  for (const prefix of ATS_PREFIXES) {
    if (host.startsWith(prefix)) host = host.substring(prefix.length);
  }
  return host;
}

function pickDomain(text) {
  const urls = String(text).match(URL_RE) || [];
  for (const u of urls) {
    const m = u.match(HOST_RE);
    if (!m) continue;
    const host = cleanHost(m[0]);
    if (isNoise(host)) continue;
    return { domain: host, url: u.replace(/[.,;:)\]]+$/, '') };
  }
  return null;
}

function parseTz(t) {
  if (/utc\+2|eastern europe|athens|bucharest|cairo|kyiv|kiev|tallinn|estonia|helsinki|finland|latvia|vilnius|romania|bulgaria|greece/i.test(t)) return 2;
  if (/utc\+1|cet\b|cest\b|central europe|berlin|paris|madrid|rome|amsterdam|tunis|munich|barcelona|warsaw|prague|vienna|stockholm|oslo|copenhagen|sweden|norway|denmark|poland|germany|france|spain|italy|netherlands|belgium|austria|switzerland/i.test(t)) return 1;
  if (/utc\+0|\bgmt\b|\buk\b|london|dublin|lisbon|ireland|england|scotland/i.test(t)) return 0;
  if (/utc\+3|moscow|istanbul|riyadh|nairobi|doha|bahrain|kuwait|saudi|turkey|israel|tel aviv/i.test(t)) return 3;
  if (/utc\+4|dubai|\buae\b|baku|tbilisi|yerevan|georgia|armenia|azerbaijan/i.test(t)) return 4;
  if (/remote[^\n]{0,40}(europe|emea|\beu\b)|(europe|emea)[^\n]{0,40}remote|european hours|\beu hours/i.test(t)) return 1;
  if (/\best\b|\bedt\b|eastern time|new york|toronto|central time|chicago|pacific time|los angeles|seattle|united states|\bus only|\busa\b|\bus\b|americas/i.test(t)) return -5;
  return null;
}

function parseFunding(t) {
  if (/series\s*a/i.test(t)) return 'series_a';
  if (/series\s*b/i.test(t)) return 'series_b';
  if (/series\s*[c-f]\b/i.test(t)) return 'series_c';
  if (/pre-?seed|\bseed\b/i.test(t)) return 'seed';
  if (/bootstrapped|profitable|self-funded/i.test(t)) return 'bootstrapped';
  return 'unknown';
}

function parseHeadcount(t) {
  const m = t.match(/(?:we(?:'re| are)?|team of|currently|now)\s+(\d{1,4})\s+(?:people|employees|engineers|folks)/i)
         || t.match(/(\d{1,4})\s+(?:people|employees)\b/i);
  const n = m ? Number(m[1]) : NaN;
  return Number.isFinite(n) && n > 0 && n <= 10000 ? n : 15;
}

// Returns the top-level comments (= company posts) of one thread
async function loadTopLevel(storyId) {
  let top = [];
  try {
    const thread = await this.helpers.httpRequest({ method: 'GET', json: true, url: 'https://hn.algolia.com/api/v1/items/' + storyId });
    top = (thread.children || []).filter(c => c && c.text).map(c => ({ text: c.text }));
  } catch (e) { top = []; }
  if (!top.length) {
    try {
      const res = await this.helpers.httpRequest({
        method: 'GET', json: true,
        url: 'https://hn.algolia.com/api/v1/search?tags=comment,story_' + storyId + '&hitsPerPage=1000'
      });
      top = (res.hits || [])
        .filter(h => h && String(h.parent_id) === storyId && (h.comment_text || h.text))
        .map(h => ({ text: h.comment_text || h.text }));
    } catch (e) { top = []; }
  }
  return top;
}

try {
  // Newest "Who is hiring" threads from the last ~75 days (usually 2 or 3 monthly threads)
  const since = Math.floor(Date.now() / 1000) - 75 * 24 * 3600;
  const search = await this.helpers.httpRequest({
    method: 'GET', json: true,
    url: 'https://hn.algolia.com/api/v1/search_by_date?tags=story&query=' + encodeURIComponent('Ask HN: Who is hiring') +
         '&numericFilters=created_at_i%3E' + since + '&hitsPerPage=20'
  });

  const stories = (search.hits || [])
    .filter(h => /^ask hn: who is hiring/i.test(h.title || '') && /\([a-z]+ \d{4}\)/i.test(h.title || ''))
    .sort((a, b) => b.created_at_i - a.created_at_i)
    .slice(0, threadsWanted);

  if (!stories.length) return [{ json: { __error: 'hn_hiring: no monthly thread found', __counters: C } }];
  C.threads = stories.length;

  const out = [];
  const seenDomains = new Set();

  for (const story of stories) {
    const storyId = String(story.objectID);
    const topLevel = await loadTopLevel.call(this, storyId);
    C.top_level += topLevel.length;

    for (const c of topLevel) {
      if (out.length >= cap) break;
      const clean = String(c.text)
        .replace(/<[^>]*>/g, ' ')
        .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
        .replace(/&#x27;/g, "'").replace(/&quot;/g, '"').replace(/&#x2F;/g, '/')
        .replace(/\s+/g, ' ').trim();
      const lower = clean.toLowerCase();

      if (keywords.length && !keywords.some(k => lower.includes(k))) continue;
      C.keyword_hits++;
      if (strong.length && !strong.some(k => hasWord(lower, k))) { C.weak_drop++; continue; }

      let picked = null;
      const hrefM = String(c.text).match(/href=["']([^"']+)["']/i);
      if (hrefM) {
        const hm = hrefM[1].match(HOST_RE);
        const host = hm ? cleanHost(hm[0]) : '';
        if (host && !isNoise(host)) picked = { domain: host, url: hrefM[1] };
      }
      if (!picked) picked = pickDomain(clean);
      if (!picked) { C.url_fail++; continue; }
      if (seenDomains.has(picked.domain)) { C.dup_drop++; continue; }
      seenDomains.add(picked.domain);

      const tz = parseTz(lower);
      if (tz === null) C.tz_null++;

      out.push({
        json: {
          source: 'hn_hiring',
          company_name: picked.domain,
          domain: picked.domain,
          website: picked.url,
          industry: 'software',
          company_type: 'startup',
          employee_count: parseHeadcount(lower),
          location_raw: 'Remote',
          country: '',
          timezone_utc_offset: tz,
          funding_stage: parseFunding(lower),
          description_text: clean.slice(0, 2500),   // was 1000: keeps this gate and Process Accounts consistent
          status: 'new',
          hn_thread: storyId
        }
      });
    }
  }

  const note = 'hn stats: threads=' + C.threads + ' top_level=' + C.top_level + ' keyword_hits=' + C.keyword_hits + ' weak=' + C.weak_drop +
               ' url_fail=' + C.url_fail + ' dup=' + C.dup_drop + ' tz_null=' + C.tz_null + ' returned=' + out.length;

  if (!out.length) return [{ json: { __error: 'hn_hiring: 0 companies after gates | ' + note, __counters: C } }];
  return out.concat([{ json: { __skipped: note } }]);

} catch (e) {
  return [{ json: { __error: 'hn_hiring: ' + String(e.message || e).slice(0, 200), __counters: C } }];
}

