  const n8nStack = String(row.tech_stack || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
  const union = Array.from(new Set(n8nStack.concat(clayStack)));
  const added = union.length - n8nStack.length;
  if (added > 0) row.tech_stack = union.join(', ');

  // 4. Funding: upgrade only from 'unknown'
  const cs = String(c.funding_stage_clay || '').toLowerCase().trim();
  let upgraded = false;
  if (String(row.funding_stage || '') === 'unknown' && STAGES.includes(cs)) {
