  // Explainable re-score: parse stored components, add ONLY new evidence
  const bm = String(r.score_breakdown || '').match(/icp=(\d+);\s*budget=(\d+);\s*automation=(\d+);\s*timezone=(\d+)/i);
  const icp = bm ? Number(bm[1]) : 50;
